def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = grid[0][0]

    for color in range(10):
        points = [(r, c) for r in range(h) for c in range(w)
                  if grid[r][c] == color]
        for i, (r1, c1) in enumerate(points):
            for r2, c2 in points[i + 1:]:
                dr, dc = r2 - r1, c2 - c1
                if abs(dr) != abs(dc) or dr == 0:
                    continue

                # Continue the diagonal from each endpoint, but only outward.
                for r, c, sr, sc in ((r1 - dr, c1 - dc, -dr, -dc),
                                     (r2 + dr, c2 + dc, dr, dc)):
                    while 0 <= r < h and 0 <= c < w:
                        if grid[r][c] != background:
                            break
                        out[r][c] = color
                        r += sr
                        c += sc
    return out
